package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.type.JavaType;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen0Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> mockConfig;
    private com.fasterxml.jackson.databind.introspect.AnnotationIntrospector mockAi;
    private JavaType mockBaseType;
    private AnnotatedMember mockProperty;

    // Dummy classes for testing hierarchy
    public static class Base {}
    public static class Sub1 extends Base {}
    public static class Sub2 extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        mockBaseType = mock(JavaType.class);
        mockProperty = mock(AnnotatedMember.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectWithOnlyBaseType() {
        // Scenario: No property, no registered subtypes. Only the base type itself should be processed.
        when(mockAi.findSubtypes(any())).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        // Should contain at least the base type itself (via _combineNamedAndUnnamed logic)
        boolean foundBase = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Base.class)) {
                foundBase = true;
                break;
            }
        }
        assertTrue("Result should contain the base type", foundBase);
    }

    @Test
    public void testCollectWithPropertySubtypes() {
        // Scenario: Property provides subtypes via AnnotationIntrospector
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedSub1));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean foundSub1 = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub1.class)) {
                foundSub1 = true;
            }
        }
        assertTrue("Result should contain subtype from property", foundSub1);
    }

    @Test
    public void testCollectWithRegisteredSubtypes() {
        // Scenario: Subtypes registered via registerSubtypes
        resolver.registerSubtypes(new NamedType(Sub2.class, "sub2"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        boolean foundSub2 = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub2.class)) {
                foundSub2 = true;
            }
        }
        assertTrue("Result should contain registered subtype", foundSub2);
    }

    @Test
    public void testCollectWithAllThreeSources() {
        // Scenario: Hierarchy + Property + Registered
        resolver.registerSubtypes(new NamedType(Sub2.class, "sub2"));
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedSub1));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        boolean foundSub1 = false;
        boolean foundSub2 = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub1.class)) foundSub1 = true;
            if (nt.getType().equals(Sub2.class)) foundSub2 = true;
        }
        assertTrue("Should find subtype from property", foundSub1);
        assertTrue("Should find subtype from registration", foundSub2);
    }

    @Test
    public void testRegisteredSubtypeNotAssignable() {
        // Scenario: Registered subtype is NOT a subclass of Base
        resolver.registerSubtypes(new NamedType(Unrelated.class, "unrelated"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        for (NamedType nt : result) {
            assertNotEquals("Unrelated type should not be included", Unrelated.class, nt.getType());
        }
    }

    @Test
    public void testPropertySubtypesNullCase() {
        // Scenario: ai.findSubtypes returns null
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Should not crash and simply proceed to registration
    }

    @Test
    public void testDuplicateSubtypesHandled() {
        // Scenario: Subtype is both in property and registered. typesHandled should prevent duplicates.
        resolver.registerSubtypes(new NamedType(Sub1.class, "sub1"));
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedSub1));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        long sub1Count = result.stream().filter(nt -> nt.getType().equals(Sub1.class)).count();
        // Depending on _combineNamedAndUnnamed implementation, we ensure it doesn't explode/duplicate incorrectly
        assertTrue("Should handle duplicates gracefully", sub1Count <= 2); 
    }
}
